import { SupportedMimeTypes } from '../../lib/drive/constants';
import { MAX_PREVIEW_FILE_SIZE, MAX_PREVIEW_TEXT_SIZE, isPreviewAvailable } from '../../lib/helpers/preview';

describe('isPreviewAvailable()', () => {
    const textTypes = ['text/any', 'application/json'];
    const supportedTypes = [SupportedMimeTypes.jpg, 'video/any', 'audio/any', ...textTypes];
    const unsupportedTypes = ['image/any', 'application/any', 'any'];

    supportedTypes.forEach((type) => {
        describe(`for supported type ${type}`, () => {
            it('should return positive answer without size', () => {
                expect(isPreviewAvailable(type)).toBe(true);
            });

            const size = textTypes.includes(type) ? MAX_PREVIEW_TEXT_SIZE : MAX_PREVIEW_FILE_SIZE;
            it('should return positive answer with reasonable size', () => {
                expect(isPreviewAvailable(type, size / 2)).toBe(true);
            });

            it('should return negative answer with too big size', () => {
                expect(isPreviewAvailable(type, size + 1)).toBe(false);
            });
        });
    });

    unsupportedTypes.forEach((type) => {
        it(`should return negative answer for unsupported ${type} without size`, () => {
            expect(isPreviewAvailable(type)).toBe(false);
        });
    });
});
import { SupportedMimeTypes, THUMBNAIL_MAX_SIZE } from '@proton/shared/lib/drive/constants';

import { scaleImageFile } from './image';
import { ThumbnailType } from './interface';

describe('scaleImageFile', () => {
    beforeEach(() => {
        global.URL.createObjectURL = jest.fn(() => 'url');
        // Image under test does not handle events.
        // @ts-ignore
        global.Image = class {
            addEventListener(type: string, listener: (value?: any) => void) {
                if (type === 'load') {
                    listener();
                }
            }
        };
        // @ts-ignore
        global.HTMLCanvasElement.prototype.getContext = jest.fn(() => {
            return {
                drawImage: jest.fn(),
                fillRect: jest.fn(),
            };
        });
        global.HTMLCanvasElement.prototype.toBlob = jest.fn((callback) => {
            callback(new Blob(['abc']));
        });
    });

    it('returns the scaled image', async () => {
        await expect(scaleImageFile({ file: new Blob(), mimeType: SupportedMimeTypes.jpg })).resolves.toEqual({
            width: undefined,
            height: undefined,
            thumbnails: [
                {
                    thumbnailData: new Uint8Array([97, 98, 99]),
                    thumbnailType: ThumbnailType.PREVIEW,
                },
            ],
        });
    });
    it('returns multiple scaled image', async () => {
        await expect(
            scaleImageFile({
                file: new Blob(),
                mimeType: SupportedMimeTypes.jpg,
                thumbnailTypes: [ThumbnailType.PREVIEW, ThumbnailType.HD_PREVIEW],
            })
        ).resolves.toEqual({
            width: undefined,
            height: undefined,
            thumbnails: [
                {
                    thumbnailData: new Uint8Array([97, 98, 99]),
                    thumbnailType: ThumbnailType.PREVIEW,
                },
                {
                    thumbnailData: new Uint8Array([97, 98, 99]),
                    thumbnailType: ThumbnailType.HD_PREVIEW,
                },
            ],
        });
    });

    it('fails due to problem to load the image', async () => {
        // @ts-ignore
        global.Image = class {
            addEventListener(type: string, listener: (value?: any) => void) {
                if (type === 'error') {
                    listener(new Error('Failed to load image'));
                }
            }
        };
        await expect(scaleImageFile({ file: new Blob(), mimeType: SupportedMimeTypes.jpg })).rejects.toEqual(
            new Error('Image cannot be loaded')
        );
    });

    it('fails due to no small enough thumbnail', async () => {
        global.HTMLCanvasElement.prototype.toBlob = jest.fn((callback) => {
            callback(new Blob(['x'.repeat(THUMBNAIL_MAX_SIZE + 1)]));
        });
        await expect(scaleImageFile({ file: new Blob(), mimeType: SupportedMimeTypes.jpg })).rejects.toEqual(
            new Error('Cannot create small enough thumbnail')
        );
    });

    it('fails due to no blob', async () => {
        global.HTMLCanvasElement.prototype.toBlob = jest.fn((callback) => {
            callback(null);
        });
        await expect(scaleImageFile({ file: new Blob(), mimeType: SupportedMimeTypes.jpg })).rejects.toEqual(
            new Error('Blob not available')
        );
    });
});
